import Foundation
import SQLite3

// MARK: - Configuration
struct ServerConfig {
    static let maxPageSize = 100
    static let defaultPageSize = 20
    static let sessionTimeout: TimeInterval = 3600
}

// MARK: - Session Store
class SessionStore {
    private var sessions: [String: (userId: String, role: String, expires: Date)] = [:]
    private let lock = NSLock()

    func createSession(userId: String, role: String) -> String {
        let token = UUID().uuidString
        lock.lock()
        sessions[token] = (userId: userId, role: role, expires: Date().addingTimeInterval(ServerConfig.sessionTimeout))
        lock.unlock()
        return token
    }

    func validateSession(_ token: String) -> (userId: String, role: String)? {
        lock.lock()
        defer { lock.unlock() }
        guard let session = sessions[token], session.expires > Date() else {
            sessions.removeValue(forKey: token)
            return nil
        }
        return (session.userId, session.role)
    }
}

// MARK: - Database Layer
class UserDatabase {
    private var db: OpaquePointer?

    init(path: String = ":memory:") {
        sqlite3_open(path, &db)
        execute("CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT, email TEXT, role TEXT, department TEXT)")
        execute("CREATE TABLE IF NOT EXISTS documents (id TEXT, owner_id TEXT, title TEXT, content TEXT, classification TEXT)")
        seedData()
    }

    private func execute(_ sql: String) {
        sqlite3_exec(db, sql, nil, nil, nil)
    }

    private func seedData() {
        execute("INSERT INTO users VALUES ('u1','alice','alice@corp.com','admin','engineering')")
        execute("INSERT INTO users VALUES ('u2','bob','bob@corp.com','user','marketing')")
        execute("INSERT INTO documents VALUES ('d1','u1','Secret Plan','Top secret content','classified')")
        execute("INSERT INTO documents VALUES ('d2','u2','Marketing Brief','Public content','public')")
    }

    // Parameterized query for safe lookups
    func findUser(byId id: String) -> [String: String]? {
        let sql = "SELECT id, username, email, role, department FROM users WHERE id = ?"
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else { return nil }
        sqlite3_bind_text(stmt, 1, (id as NSString).utf8String, -1, nil)
        defer { sqlite3_finalize(stmt) }
        guard sqlite3_step(stmt) == SQLITE_ROW else { return nil }
        return [
            "id": String(cString: sqlite3_column_text(stmt, 0)),
            "username": String(cString: sqlite3_column_text(stmt, 1)),
            "email": String(cString: sqlite3_column_text(stmt, 2)),
            "role": String(cString: sqlite3_column_text(stmt, 3)),
            "department": String(cString: sqlite3_column_text(stmt, 4))
        ]
    }

    /// Search documents with filtering - uses parameterized queries for values
    /// and strict whitelist for column selection
    func searchDocuments(columns: [String], ownerId: String, classification: String?, page: Int, pageSize: Int) -> [[String: String]] {
        let validColumns = Set(["id", "title", "classification", "owner_id"])
        let selectedColumns = columns.filter { validColumns.contains($0) }

        guard !selectedColumns.isEmpty else { return [] }

        let columnList = selectedColumns.joined(separator: ", ")
        var sql = "SELECT \(columnList) FROM documents WHERE owner_id = ?"
        var bindings: [String] = [ownerId]

        if let cls = classification {
            sql += " AND classification = ?"
            bindings.append(cls)
        }

        let offset = computeOffset(page: page, pageSize: pageSize)
        let limit = min(pageSize, ServerConfig.maxPageSize)
        sql += " LIMIT \(limit) OFFSET \(offset)"

        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else { return [] }

        for (i, binding) in bindings.enumerated() {
            sqlite3_bind_text(stmt, Int32(i + 1), (binding as NSString).utf8String, -1, nil)
        }

        defer { sqlite3_finalize(stmt) }
        var results: [[String: String]] = []
        while sqlite3_step(stmt) == SQLITE_ROW {
            var row: [String: String] = [:]
            for (i, col) in selectedColumns.enumerated() {
                if let val = sqlite3_column_text(stmt, Int32(i)) {
                    row[col] = String(cString: val)
                }
            }
            results.append(row)
        }
        return results
    }

    /// Compute offset with safe arithmetic
    private func computeOffset(page: Int, pageSize: Int) -> Int {
        let safePage = max(0, page - 1)
        let safePageSize = min(max(1, pageSize), ServerConfig.maxPageSize)
        // Use checked multiplication - crash on overflow rather than silently wrapping
        return safePage * safePageSize
    }
}

// MARK: - Access Control
class AccessController {

    /// Determines if a user can access documents based on ownership and role
    func canAccessDocuments(requesterId: String, targetOwnerId: String, requesterRole: String) -> Bool {
        // Admins can access all documents
        if requesterRole == "admin" {
            return true
        }
        // Regular users can only access their own documents
        return requesterId == targetOwnerId
    }

    /// Filters classification levels based on user role
    func allowedClassifications(forRole role: String) -> [String] {
        switch role {
        case "admin": return ["public", "internal", "classified"]
        case "manager": return ["public", "internal"]
        default: return ["public"]
        }
    }

    /// Validates and sanitizes the requested owner filter
    /// Returns the effective owner ID to use for the query
    func resolveOwnerFilter(requestedOwner: String?, requesterId: String, requesterRole: String) -> String? {
        guard let owner = requestedOwner else {
            return requesterId  // Default to own documents
        }

        // Check access permission
        if canAccessDocuments(requesterId: requesterId, targetOwnerId: owner, requesterRole: requesterRole) {
            return owner
        }

        return nil  // Access denied
    }
}

// MARK: - Request Handler
class DocumentAPIHandler {
    let db: UserDatabase
    let sessions: SessionStore
    let accessControl: AccessController

    init(db: UserDatabase, sessions: SessionStore, accessControl: AccessController) {
        self.db = db
        self.sessions = sessions
        self.accessControl = accessControl
    }

    struct SearchRequest {
        let columns: [String]
        let ownerFilter: String?
        let classification: String?
        let page: Int
        let pageSize: Int
    }

    func handleSearch(sessionToken: String, request: SearchRequest) -> String {
        // Step 1: Authenticate
        guard let session = sessions.validateSession(sessionToken) else {
            return "{\"error\": \"unauthorized\"}"
        }

        // Step 2: Resolve owner filter with access control
        guard let effectiveOwner = accessControl.resolveOwnerFilter(
            requestedOwner: request.ownerFilter,
            requesterId: session.userId,
            requesterRole: session.role
        ) else {
            return "{\"error\": \"access_denied\"}"
        }

        // Step 3: Apply classification filter based on role
        let allowedCls = accessControl.allowedClassifications(forRole: session.role)
        let effectiveClassification: String?
        if let requestedCls = request.classification {
            if allowedCls.contains(requestedCls) {
                effectiveClassification = requestedCls
            } else {
                effectiveClassification = "public"  // Downgrade to public
            }
        } else {
            effectiveClassification = nil  // No filter
        }

        // Step 4: Execute search
        let results = db.searchDocuments(
            columns: request.columns,
            ownerId: effectiveOwner,
            classification: effectiveClassification,
            page: request.page,
            pageSize: request.pageSize
        )

        return serializeResults(results)
    }

    /// Escapes a string for safe inclusion inside a JSON string literal.
    private func escapeJSON(_ value: String) -> String {
        var out = ""
        out.reserveCapacity(value.count)
        for scalar in value.unicodeScalars {
            switch scalar {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\u{08}": out += "\\b"
            case "\u{0C}": out += "\\f"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            default:
                if scalar.value < 0x20 {
                    out += String(format: "\\u%04x", scalar.value)
                } else {
                    out.unicodeScalars.append(scalar)
                }
            }
        }
        return out
    }

    private func serializeResults(_ results: [[String: String]]) -> String {
        // JSON serialization with proper escaping to prevent JSON injection.
        let items = results.map { row in
            let fields = row.map { "\"\(escapeJSON($0.key))\": \"\(escapeJSON($0.value))\"" }.joined(separator: ", ")
            return "{\(fields)}"
        }.joined(separator: ", ")
        return "{\"results\": [\(items)]}"
    }
}
